<template>
<div class="app-container pool-workspace" v-loading="busy">
  <header class="page-header"><div><h2>套装选品</h2><p>按品类筛选商品，在完整方案池中选择需要的套装</p></div><div class="actions"><el-button @click="historyVisible=true;loadHistory()">继续已保存选品</el-button><el-button @click="fresh">新建选品</el-button><el-button type="primary" :disabled="!pool||!dirty" v-hasPermi="['fashion:quote:edit']" @click="save">保存选择</el-button></div></header>
  <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="space"/>
  <nav class="steps" aria-label="选品步骤"><el-button v-for="(label,i) in ['商品筛选','方案池','已选方案']" :key="label" :type="step===i?'primary':'default'" :disabled="i>0&&!pool" @click="go(i)">{{i+1}}. {{label}}<span v-if="i===2">（{{selectedCount}}）</span></el-button></nav>
  <div class="workspace-meta"><el-input v-model="form.title" placeholder="填写选品工作单名称" maxlength="100" aria-label="选品工作单名称" :disabled="step>0"/><el-tag v-if="pool" type="info">{{pool.title}} · {{pool.createdAt}}</el-tag><el-tag v-if="dirty" type="warning">选择尚未保存</el-tag></div>
  <section v-show="step===0">
    <div class="section-title"><h3>商品筛选条件</h3><span>同组分类取并集，组与组组合；颜色尺码不重复生成方案</span><el-button :disabled="form.groups.length>=4" @click="form.groups.push(blankGroup(form.groups.length))">＋增加品类组（{{form.groups.length}}/4）</el-button></div>
    <FilterGroup v-for="(g,i) in form.groups" :key="i" :group="g" :options="options" :removable="form.groups.length>1" @copy="copyGroup(i)" @reset="form.groups[i]=blankGroup(i)" @remove="form.groups.splice(i,1)"/>
    <el-form inline class="summary-bar"><el-form-item label="整套价格口径"><el-select v-model="form.priceBasis" style="width:130px"><el-option label="团购价" value="group"/><el-option label="VIP 价" value="vip"/></el-select></el-form-item><el-form-item label="整套价格区间"><el-input-number v-model="form.totalMin" :min="0" :precision="2" :controls="false" placeholder="最低"/><span class="separator">至</span><el-input-number v-model="form.totalMax" :min="0" :precision="2" :controls="false" placeholder="最高"/></el-form-item><el-form-item><el-button type="primary" v-hasPermi="['fashion:quote:edit']" @click="generate">生成方案池</el-button></el-form-item></el-form>
    <el-alert v-if="pool" title="重新生成会创建独立方案池版本；旧池已保存的选择仍可从“继续已保存选品”打开。" :closable="false" type="info"/>
  </section>
  <section v-if="pool&&step>0">
    <div class="stats"><span>原始组合 <strong>{{pool.rawCount.toLocaleString()}}</strong></span><span>符合条件 <strong>{{pool.total.toLocaleString()}}</strong></span><span>已选 <strong>{{selectedCount.toLocaleString()}}</strong></span></div>
    <div class="table-toolbar"><el-input v-model="query.keyword" clearable placeholder="搜索主 SKU、品号、货号或名称" style="width:300px" @keyup.enter="search"/><el-select v-if="step===1" v-model="query.sort" style="width:160px" @change="search"><el-option label="默认顺序" value="identity"/><el-option label="团购价升序" value="groupAsc"/><el-option label="团购价降序" value="groupDesc"/><el-option label="VIP 价升序" value="vipAsc"/><el-option label="VIP 价降序" value="vipDesc"/></el-select><el-button @click="search">查询</el-button><template v-if="step===1"><el-button @click="selectPage">选择本页</el-button><el-button :disabled="!!query.keyword" @click="selectAll">选择全部 {{pool.total}} 套</el-button></template><template v-else><el-button :disabled="!selectedCount" v-hasPermi="['fashion:quote:query']" @click="openTool('image')">模特试衣</el-button><el-button type="primary" :disabled="!selectedCount" v-hasPermi="['fashion:quote:export']" @click="openTool('ppt')">导出 PPT</el-button></template><el-button :disabled="compareItems.length<2" @click="compareVisible=true">对比 {{compareItems.length}} 套</el-button><el-button v-if="selectedCount" @click="clearSelection">清空已选</el-button></div>
    <el-table :data="page.items" row-key="id" v-loading="loading" border empty-text="没有符合条件的方案，请调整筛选或查询条件">
      <el-table-column label="选择" width="64" fixed><template #default="{row}"><el-checkbox :model-value="isSelected(selection,row.id)" :aria-label="`选择方案 ${row.id}`" @change="(v:unknown)=>toggle(row.id,Boolean(v))"/></template></el-table-column>
      <el-table-column :label="step===2?'方案名称':'方案编号'" width="185"><template #default="{row}"><el-input v-if="step===2" :model-value="selection.names[row.id]||''" :placeholder="row.id" maxlength="100" @update:model-value="(v:string)=>rename(row.id,v)"/><code v-else>{{row.id}}</code></template></el-table-column>
      <el-table-column v-for="(group,i) in pool.groups" :key="i" :label="group.label" min-width="220"><template #default="{row}"><div v-if="row.items[i]" class="product-cell"><ProductThumbnail v-if="row.items[i].mainImageUrl" :product-id="selection.variantSelections[row.id]?.[row.items[i].key]||row.items[i].productId"/><div v-else class="no-image">缺少主图</div><div><strong>{{row.items[i].name}}</strong><p>{{row.items[i].mainSkuCode}}</p><small>{{row.items[i].brand||'品牌未知'}}</small></div></div></template></el-table-column>
      <el-table-column label="团购合计" width="140"><template #default="{row}">{{priceRange(row.groupPriceMin,row.groupPriceMax)}}</template></el-table-column><el-table-column label="VIP 合计" width="140"><template #default="{row}">{{priceRange(row.vipPriceMin,row.vipPriceMax)}}</template></el-table-column><el-table-column label="库存" width="115"><template #default="{row}"><el-tag :type="row.stockUnknown?'warning':'info'">{{row.stockUnknown?'有待核实项':'已知库存'}}</el-tag></template></el-table-column>
      <el-table-column label="操作" width="130" fixed="right"><template #default="{row}"><el-button link type="primary" @click="details=row;detailsVisible=true">详情 / 选色</el-button><el-button link @click="addCompare(row)">加入对比</el-button><el-button v-if="step===2" link @click="moveFirst(row.id)">移到首位</el-button></template></el-table-column>
    </el-table>
    <el-pagination class="pagination" v-model:current-page="query.page" v-model:page-size="query.pageSize" :page-sizes="[20,50,100]" :total="page.total" layout="total, sizes, prev, pager, next" @current-change="loadPage" @size-change="search"/>
    <p class="hint">单池最多计算 100,000 个原始组合，超过时需缩小筛选。库存汇总不等于每个尺码都能供货；价格区间按当前池快照显示，正式报价需重新核实。</p>
  </section>
  <el-drawer v-model="detailsVisible" title="方案商品与颜色尺码" size="70%">
    <template v-if="details"><el-alert title="一个款式只占一个方案位置；选择颜色尺码仅改变该方案的展示素材，保存后原试衣图需要重新核对。" type="info" :closable="false"/><el-card v-for="item in details.items" :key="item.key" class="space"><template #header><strong>{{item.name}} / {{item.mainSkuCode}}</strong></template><el-descriptions :column="3"><el-descriptions-item label="品号">{{item.itemNo||'未知'}}</el-descriptions-item><el-descriptions-item label="货号">{{item.articleNo||'未知'}}</el-descriptions-item><el-descriptions-item label="库存合计">{{item.availableQty??'未知'}}{{item.stockUnknown?'（部分未知）':''}}</el-descriptions-item></el-descriptions><el-radio-group :model-value="selection.variantSelections[details.id]?.[item.key]" :disabled="!isSelected(selection,details.id)" @update:model-value="(v:unknown)=>chooseVariant(details!.id,item.key,String(v))"><el-radio v-for="v in item.variants" :key="v.productId" :value="v.productId">{{v.colorName}} / {{v.sizeCode}} · 库存 {{v.availableQty??'未知'}}</el-radio></el-radio-group><p v-if="!isSelected(selection,details.id)" class="hint">先选入方案，再指定展示颜色尺码。</p></el-card></template>
  </el-drawer>
  <el-dialog v-model="compareVisible" title="方案对比（最多四套）" width="92%"><div class="compare-grid"><el-card v-for="combo in compareItems" :key="combo.id"><template #header>{{selection.names[combo.id]||combo.id}} <el-button link type="danger" @click="compareItems=compareItems.filter(x=>x.id!==combo.id)">移除对比</el-button></template><div v-for="item in combo.items" :key="item.key"><ProductThumbnail v-if="item.mainImageUrl" :product-id="item.productId"/><h4>{{item.name}}</h4><p>{{item.mainSkuCode}} / {{item.brand||'品牌未知'}}</p></div><p>团购 {{priceRange(combo.groupPriceMin,combo.groupPriceMax)}}</p><p>VIP {{priceRange(combo.vipPriceMin,combo.vipPriceMax)}}</p><el-button :type="isSelected(selection,combo.id)?'success':'primary'" @click="toggle(combo.id,!isSelected(selection,combo.id))">{{isSelected(selection,combo.id)?'已选入，点击移除':'选入方案'}}</el-button></el-card></div></el-dialog>
  <el-dialog v-model="historyVisible" title="继续已保存选品" width="800px"><el-table :data="history" v-loading="historyLoading"><el-table-column prop="title" label="工作单"/><el-table-column prop="createdAt" label="创建时间"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="openExisting(row.id)">打开</el-button></template></el-table-column></el-table></el-dialog>
  <DeliveryTools v-if="pool" v-model="toolVisible" :kind="toolKind" :pool-id="pool.id" :row-version="selection.rowVersion" :selected-count="selectedCount" :combination-ids="step===2?page.items.map(x=>x.id):[]"/>
</div>
</template>
<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,ref} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {fashionRequest} from '@/api/fashion/client'
import type {RuoYiResult} from '@/api/fashion/types'
import {createPool,getPool,getPoolOptions,getPoolPage,getPoolSelection,savePoolSelection} from '@/api/fashion/pool'
import {blankGroup,isSelected,toggleSelected,priceRange,type PoolRequest,type PoolSnapshot,type PoolSelection,type PoolOptions,type PoolCombination,type PoolPage} from '@/api/fashion/poolTypes'
import FilterGroup from './FilterGroup.vue'
import DeliveryTools from './DeliveryTools.vue'
import ProductThumbnail from '../components/ProductThumbnail.vue'
const router=useRouter(),route=useRoute(),step=ref(0),busy=ref(false),loading=ref(false),error=ref(''),dirty=ref(false)
const form=reactive<PoolRequest>({title:'',groups:[blankGroup(0),blankGroup(1)],priceBasis:'group'})
const options=ref<PoolOptions>({categories:[],brands:[],seasons:[],genders:[],warehouses:[]}),pool=ref<PoolSnapshot>()
const emptySelection=():PoolSelection=>({rowVersion:0,all:false,selectedIds:[],excludedIds:[],names:{},orderedIds:[],variantSelections:{}})
const selection=ref<PoolSelection>(emptySelection()),page=ref<PoolPage>({items:[],total:0,page:1,pageSize:20,rawCount:0})
const query=reactive({page:1,pageSize:20,sort:'identity',keyword:''}),selectedCount=computed(()=>selection.value.all?Math.max(0,(pool.value?.total??0)-selection.value.excludedIds.length):selection.value.selectedIds.length)
const details=ref<PoolCombination>(),detailsVisible=ref(false),historyVisible=ref(false),historyLoading=ref(false),history=ref<{id:string;title:string;createdAt:string}[]>([]),toolVisible=ref(false),toolKind=ref<'image'|'ppt'>('image')
const compareItems=ref<PoolCombination[]>([]),compareVisible=ref(false)
function addCompare(row:PoolCombination){if(compareItems.value.some(x=>x.id===row.id))return ElMessage.info('已在对比列表');if(compareItems.value.length>=4)return ElMessage.warning('最多对比四套，请先移除一套');compareItems.value.push(row)}
let controller:AbortController|undefined,sequence=0
async function run(fn:()=>Promise<void>){error.value='';try{await fn();return true}catch(e){error.value=e instanceof Error?e.message:'操作失败，请重试';return false}}
async function loadPage(){if(!pool.value)return;const seq=++sequence;controller?.abort();controller=new AbortController();loading.value=true;try{const result=await getPoolPage(pool.value.id,{...query,selectedOnly:step.value===2},controller.signal);if(seq===sequence)page.value=result.data}catch(e){if(seq===sequence)error.value=e instanceof Error?e.message:'读取失败'}finally{if(seq===sequence)loading.value=false}}
async function search(){query.page=1;await loadPage()}
async function save(){if(!pool.value||!dirty.value)return true;busy.value=true;try{return await run(async()=>{selection.value=(await savePoolSelection(pool.value!.id,selection.value)).data;dirty.value=false;ElMessage.success('选择已保存')})}finally{busy.value=false}}
async function leaveDirty(){if(!dirty.value)return true;try{await ElMessageBox.confirm('当前选择尚未保存，是否先保存？','保存选择',{confirmButtonText:'保存并继续',cancelButtonText:'留在当前页面',type:'warning'});return await save()}catch{return false}}
async function generate(){if(!form.title.trim())return ElMessage.warning('请填写选品工作单名称');if(form.groups.some(g=>!g.categoryLeafCodes.length))return ElMessage.warning('每个筛选组至少选择一个三级分类');if(!await leaveDirty())return;busy.value=true;try{await run(async()=>{pool.value=(await createPool(JSON.parse(JSON.stringify(form)))).data;selection.value=(await getPoolSelection(pool.value.id)).data;compareItems.value=[];dirty.value=false;step.value=1;query.page=1;query.keyword='';await router.replace({query:{...route.query,poolId:pool.value.id}});await loadPage()})}finally{busy.value=false}}
async function go(next:number){if(next===2&&dirty.value&&!await save())return;step.value=next;query.page=1;query.keyword='';query.sort='identity';if(next>0)await loadPage()}
function toggle(id:string,value:boolean){toggleSelected(selection.value,id,value);dirty.value=true}
function selectPage(){page.value.items.forEach(x=>toggle(x.id,true))}
async function selectAll(){try{await ElMessageBox.confirm(`选入本方案池全部 ${pool.value?.total} 套，可跨页排除个别方案。`,'选择全部',{type:'info'});selection.value.all=true;selection.value.selectedIds=[];selection.value.excludedIds=[];dirty.value=true}catch{}}
function clearSelection(){selection.value.all=false;selection.value.selectedIds=[];selection.value.excludedIds=[];dirty.value=true}
function rename(id:string,name:string){selection.value.names[id]=name;dirty.value=true}
async function moveFirst(id:string){selection.value.orderedIds=[id,...selection.value.orderedIds.filter(x=>x!==id)];dirty.value=true;if(await save())await loadPage()}
function chooseVariant(id:string,key:string,productId:string){selection.value.variantSelections[id]={...selection.value.variantSelections[id],[key]:productId};dirty.value=true}
function copyGroup(i:number){if(form.groups.length>=4)return ElMessage.warning('最多四个筛选组');form.groups.push({...JSON.parse(JSON.stringify(form.groups[i])),label:`品类 ${form.groups.length+1}`})}
async function openExisting(id:string){if(!await leaveDirty())return;busy.value=true;try{await run(async()=>{const [p,s]=await Promise.all([getPool(id),getPoolSelection(id)]);pool.value=p.data;selection.value=s.data;compareItems.value=[];if(p.data.request)Object.assign(form,p.data.request);dirty.value=false;historyVisible.value=false;step.value=1;query.page=1;query.keyword='';await router.replace({query:{...route.query,poolId:id}});await loadPage()})}finally{busy.value=false}}
async function loadHistory(){historyLoading.value=true;try{history.value=(await fashionRequest<RuoYiResult<typeof history.value>>({path:'pools'})).data}catch(e){error.value=e instanceof Error?e.message:'历史读取失败'}finally{historyLoading.value=false}}
async function fresh(){if(!await leaveDirty())return;pool.value=undefined;selection.value=emptySelection();compareItems.value=[];step.value=0;Object.assign(form,{title:'',groups:[blankGroup(0),blankGroup(1)],priceBasis:'group',totalMin:undefined,totalMax:undefined});await router.replace({query:{}})}
async function openTool(kind:'image'|'ppt'){if(dirty.value&&!await save())return;await loadPage();toolKind.value=kind;toolVisible.value=true}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(async()=>await leaveDirty())
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);try{options.value=(await getPoolOptions()).data;if(typeof route.query.poolId==='string')await openExisting(route.query.poolId)}catch(e){error.value=e instanceof Error?e.message:'加载失败'}})
onBeforeUnmount(()=>{controller?.abort();window.removeEventListener('beforeunload',beforeUnload)})
</script>
<style scoped>
.compare-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}.pool-workspace{max-width:1800px;margin:auto}.page-header,.actions,.steps,.section-title,.table-toolbar,.stats,.workspace-meta{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.page-header{justify-content:space-between}.page-header h2{margin:0}.page-header p,.hint{color:var(--el-text-color-secondary);font-size:13px}.steps{padding:16px 0;border-bottom:1px solid var(--el-border-color)}.steps .el-button{margin:0;min-width:160px}.workspace-meta{margin:20px 0}.workspace-meta>.el-input{max-width:360px}.section-title h3{margin-right:8px}.section-title span{flex:1;font-size:13px;color:var(--el-text-color-secondary)}.summary-bar{padding:18px 18px 0;background:var(--el-fill-color-light);border-radius:8px}.separator{padding:0 8px}.stats{padding:16px;background:var(--el-color-primary-light-9);border-radius:6px;margin-bottom:16px;gap:32px}.stats strong{font-size:20px;color:var(--el-color-primary)}.table-toolbar{margin-bottom:12px}.product-cell{display:flex;gap:10px;align-items:center}.product-cell :deep(.thumbnail),.no-image{width:68px;height:80px;flex-shrink:0}.no-image{display:grid;place-items:center;background:var(--el-fill-color-light);color:var(--el-text-color-secondary);font-size:12px}.product-cell p{margin:6px 0;font-size:12px;overflow-wrap:anywhere}.pagination{margin-top:16px;justify-content:flex-end;max-width:100%;overflow-x:auto}.space{margin:16px 0}
</style>
